package app.routia;
import android.app.*;
import android.content.*;
import android.os.*;
import android.view.accessibility.*;
import android.accessibilityservice.AccessibilityService;
import java.time.*;
public class UiSmokeInstrumentation extends Instrumentation {
    private int checks;private void check(boolean ok,String msg){checks++;if(!ok)throw new AssertionError(msg);}
    @Override public void onCreate(Bundle b){super.onCreate(b);start();}
    private AccessibilityNodeInfo find(String text){AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(root==null)return null;for(AccessibilityNodeInfo n:root.findAccessibilityNodeInfosByText(text))if(text.equals(n.getText()==null?"":n.getText().toString()))return n;return null;}
    private AccessibilityNodeInfo await(String text){long deadline=SystemClock.uptimeMillis()+8000;while(SystemClock.uptimeMillis()<deadline){AccessibilityNodeInfo n=find(text);if(n!=null)return n;SystemClock.sleep(100);}throw new AssertionError("UI text missing: "+text);}
    private void tap(String s){AccessibilityNodeInfo n=await(s);while(!n.isClickable()&&n.getParent()!=null)n=n.getParent();check(n.performAction(AccessibilityNodeInfo.ACTION_CLICK),"Tap "+s);waitForIdleSync();SystemClock.sleep(350);}
    private void send(PendingIntent i){runOnMainSync(()->{try{i.send();}catch(PendingIntent.CanceledException e){throw new RuntimeException(e);}});SystemClock.sleep(600);waitForIdleSync();}
    @Override public void onStart(){Bundle out=new Bundle();try{
        if(!Build.HARDWARE.contains("ranchu")&&!Build.HARDWARE.contains("goldfish"))throw new AssertionError("Emulator only");Context c=getTargetContext();Store s=Store.get(c);if(!s.habits().isEmpty())throw new AssertionError("Use an empty emulator app");
        startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));tap("例からつくる · 英語");tap("保存");check(s.habits().size()==1,"Goal-only creation");long id=s.habits().get(0).id();LocalDate today=LocalDate.now();check(s.habit(id).cue().isEmpty(),"UI cue optional");
        tap("✅ 最低達成");await("小さな一歩、大成功。");check(s.level(id,today)==1,"Minimum saves");tap("今日は、ここまででも十分。");tap("🏆 通常ゴールも達成した");await("やったね、達成！");tap("今日は、ここまででも十分。");check(s.level(id,today)==2,"Full saves");
        tap("記録を修正");AccessibilityNodeInfo selected=await("🏆 通常ゴール達成");check(selected.isChecked(),"Current correction selected");tap("✅ 最低ゴール達成");check(await("✅ 最低ゴール達成").isChecked(),"New correction selected");check(s.level(id,today)==2,"Selection does not save prematurely");tap("変更を保存");check(s.level(id,today)==1,"Explicit correction saves");
        s.getWritableDatabase().execSQL("UPDATE habits SET created=? WHERE id=?",new Object[]{today.minusDays(1000).toString(),id});for(int i=1;i<=100;i++)s.getWritableDatabase().execSQL("INSERT INTO records(habit_id,day,level,note) VALUES(?,?,?,?)",new Object[]{id,today.minusDays(i*8L).toString(),i%2+1,"過去の記録 "+i});
        tap("成果");await("積み重ねを、見てみよう。");await("🔥 1日連続！");tap("月");tap("年");check(s.entries(id,today.minusDays(1000),today).size()==101,"Historical source includes old records");tap("◀ 前年");tap("翌年 ▶");tap("年");tap("月");tap("月");tap("週");tap("週");tap("年");tap("設定");await("続けやすさを、整える。");tap("今日");
        getUiAutomation().performGlobalAction(AccessibilityService.GLOBAL_ACTION_HOME);SystemClock.sleep(300);long b=s.saveHabit(0,"","読む","1ページ","count",10,"ページ");send(Reminders.action(c,b,1,today.toString(),"widget"));check(s.level(b,today)==1,"Background widget saves");AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();check(root!=null&&!"app.routia".contentEquals(root.getPackageName()),"Widget does not launch app");send(Reminders.action(c,b,2,today.toString(),"widget"));send(Reminders.action(c,b,1,today.toString(),"widget"));check(s.level(b,today)==2,"No stale downgrade");
        long t=s.saveHabit(0,"","ストレッチ","背伸び1回","time",1,"分");NotificationManager nm=c.getSystemService(NotificationManager.class);runOnMainSync(()->{Reminders.showDaily(c,0,false);Reminders.all(c);});check(nm.getActiveNotifications().length==1,"One combined reminder remains");Notification n=nm.getActiveNotifications()[0].getNotification();send(n.actions[0].actionIntent);check(s.level(t,today)==1,"Notification saves");check(nm.getActiveNotifications().length==0,"Recording removes card without extra alert");
        s.record(t,today,0,true);send(Reminders.action(c,t,2,today.minusDays(1).toString(),"widget"));check(s.level(t,today)==0,"Stale date rejected");
        runOnMainSync(()->Focus.start(c,t,1));long session=Focus.prefs(c).getLong("session",0);Focus.prefs(c).edit().putLong("end",SystemClock.elapsedRealtime()+30000).commit();Focus.pause(c);long left=Focus.remaining(c);SystemClock.sleep(150);check(Focus.paused(c)&&Focus.remaining(c)==left,"Paused countdown stable");check(!Focus.complete(c),"Paused session cannot complete");Focus.resume(c);check(!Focus.paused(c)&&Focus.remaining(c)<=left&&Focus.remaining(c)>left-1000,"Resume remaining time");check(Focus.prefs(c).getLong("session",0)==session,"Resume same session");Focus.checkpoint(c);long checkpoint=Focus.prefs(c).getLong("left",-1);Focus.prefs(c).edit().putInt("boot",-99).commit();check(Focus.paused(c)&&Focus.remaining(c)==checkpoint,"Reboot restores checkpoint as paused");Focus.resume(c);Focus.prefs(c).edit().putLong("end",SystemClock.elapsedRealtime()-1).commit();check(Focus.complete(c),"Timer completes once");check(!Focus.complete(c),"Timer completion idempotent");check(s.entry(t,today).amount()==1d,"Timer adds minutes");check(s.level(t,today)==2,"Timer meets daily target");check(s.focused(t,today,today)==60,"Timer reports separate focus total");Focus.clear(c,false);
        runOnMainSync(()->{Reminders.showDaily(c,Reminders.times(c).length-1,true);});check(nm.getActiveNotifications().length==0,"All done suppresses notification");
        s.record(t,today,0,true);runOnMainSync(()->{Reminders.showDaily(c,Reminders.times(c).length-1,true);});check(nm.getActiveNotifications().length==1,"Last daily reminder appears");nm.cancel("daily",1);runOnMainSync(()->{Reminders.showDaily(c,Reminders.times(c).length-1,true);});check(nm.getActiveNotifications().length==0,"Duplicate slot cannot re-alert");
        startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));check(s.habits().size()==3,"Three fixture habits retained");
        out.putString("stream","PASS "+checks+" UI/background/focus assertions\n");finish(Activity.RESULT_OK,out);
    }catch(Throwable t){out.putString("stream","FAIL after "+checks+": "+t+"\n");finish(Activity.RESULT_CANCELED,out);}}
}
